def long_mirrors(tape, k):
    n = len(tape)
    count = 0
    for centre in range(2 * n - 1):
        lo, hi = centre // 2, (centre + 1) // 2
        while lo >= 0 and hi < n and tape[lo] == tape[hi]:
            if hi - lo + 1 >= k:
                count += 1
            lo -= 1
            hi += 1
    return count

